"""The group domain of the `math_data` database, generated by
`python -m bridge_mcp.generate groups`."""

from bridge_mcp.mathql.database import Column, ForeignKey, Schema
from bridge_mcp.mathql.types import BoolType, IntType, ListType, StringType, Ty

_COLUMNS: tuple[tuple[str, Ty, str], ...] = (
    ("order", IntType(), "the order: the number of elements"),
    ("index", IntType(), "the index in GAP's SmallGroups library for this order"),
    (
        "structure_description",
        StringType(),
        "GAP's structure description, e.g. 'S4' or 'C2 x D8'; readable but not a "
        "complete isomorphism invariant",
    ),
    ("is_abelian", BoolType(), "whether the group is abelian"),
    ("is_cyclic", BoolType(), "whether the group is cyclic"),
    ("is_nilpotent", BoolType(), "whether the group is nilpotent"),
    ("is_solvable", BoolType(), "whether the group is solvable"),
    ("is_supersolvable", BoolType(), "whether the group is supersolvable"),
    ("is_simple", BoolType(), "whether the group is simple"),
    ("is_perfect", BoolType(), "whether the group equals its derived subgroup"),
    ("exponent", IntType(), "the least common multiple of the element orders"),
    ("num_conjugacy_classes", IntType(), "the number of conjugacy classes"),
    ("min_generators", IntType(), "the size of a smallest generating set"),
    ("center_order", IntType(), "the order of the center"),
    ("derived_subgroup_order", IntType(), "the order of the derived subgroup"),
    ("frattini_order", IntType(), "the order of the Frattini subgroup"),
    (
        "abelianization",
        ListType(IntType()),
        "the abelian invariants of the abelianization G/[G,G]",
    ),
    ("automorphism_group_order", IntType(), "the order of the automorphism group"),
    ("derived_length", IntType(), "the derived length; undefined when not solvable"),
    (
        "nilpotency_class",
        IntType(),
        "the nilpotency class; undefined when not nilpotent",
    ),
    (
        "cayley_generators",
        ListType(StringType()),
        "the generating set of the Cayley graph, as words in GAP's presentation; "
        "undefined above order 100",
    ),
)

GROUP = Schema(
    table="small_group",
    columns={
        name: Column(name, ty, name in ("order", "index"), doc) for name, ty, doc in _COLUMNS
    },
    foreign_keys={
        "cayley_graph": ForeignKey(
            "Graph",
            (("cayley_graph", "graph6"),),
            "the Cayley graph on the minimal generating set (undirected, without "
            "the identity); undefined above order 100",
        )
    },
    doc=(
        "A finite group of order at most 127, identified by its GAP SmallGroups id "
        "(order, index)."
    ),
)

DOMAINS = {"Group": GROUP}
